package com.company.generated.controller;

import com.company.generated.units.u66bf2c108225.ErrorReply;
import com.company.generated.units.u66bf2c108225.StandardErrorRSFmtMapper;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

@ControllerAdvice
public class GlobalExceptionHandler {

    private final StandardErrorRSFmtMapper errorMapper = new StandardErrorRSFmtMapper();

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleException(Exception ex) {
        try {
            ErrorReply reply = new ErrorReply("99", "0", ex.getMessage() != null ? ex.getMessage() : "Technical error: unexpected system failure", "REQ-001");
            String errorXml = errorMapper.format(reply);
            return ResponseEntity.status(500).contentType(MediaType.APPLICATION_XML).body(errorXml);
        } catch (Exception e) {
            return ResponseEntity.status(500).contentType(MediaType.APPLICATION_XML).body("<ErrorReply><ErrorCategory>99</ErrorCategory><ErrorNumber>0</ErrorNumber><ErrorDescription>Technical error</ErrorDescription><RequestId>REQ-001</RequestId></ErrorReply>");
        }
    }
}

