import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/transfer-funds")
public class TransferFundsOpController {

    private final TransferFundsOpService service;

    public TransferFundsOpController(TransferFundsOpService service) {
        this.service = service;
    }

    @PostMapping(consumes = MediaType.APPLICATION_XML_VALUE, produces = MediaType.APPLICATION_XML_VALUE)
    public ResponseEntity<String> execute(@RequestBody TransferFundsRequestXml requestXml) throws Exception {
        String result = service.execute(requestXml);
        return ResponseEntity.ok(result);
    }
}

