    @Test
    public void testWiring() {
        try (AnnotationConfigApplicationContext context = new AnnotationConfigApplicationContext(TransferFundsOpConfiguration.class)) {
            TransferFundsOpService service = context.getBean(TransferFundsOpService.class);
            assertNotNull(service);

            assertNotNull(context.getBean("CoreBankingRejected", CoreBankingRejectedStep.class));
            assertNotNull(context.getBean("SkipFraudOnTimeout", SkipFraudOnTimeoutStep.class));
            assertNotNull(context.getBean("ExecuteTransfer", ExecuteTransferStep.class));
            assertNotNull(context.getBean("DailyLimitExceeded", DailyLimitExceededStep.class));
            assertNotNull(context.getBean("TransferAlreadyProcessed", TransferAlreadyProcessedStep.class));
            assertNotNull(context.getBean("FraudCheck", FraudCheckStep.class));
            assertNotNull(context.getBean("FraudSuspected", FraudSuspectedStep.class));
            assertNotNull(context.getBean("ValidationFailed", ValidationFailedStep.class));
            assertNotNull(context.getBean("InsufficientFunds", InsufficientFundsStep.class));
            assertNotNull(context.getBean("ValidateTransfer", ValidateTransferStep.class));
            assertNotNull(context.getBean("AccountNotEligible", AccountNotEligibleStep.class));
            assertNotNull(context.getBean("TechnicalError", TechnicalErrorStep.class));
            assertNotNull(context.getBean("CheckLimits", CheckLimitsStep.class));
            assertNotNull(context.getBean("DatabaseError", DatabaseErrorStep.class));
        }
    }
